import {commentCard} from './comment-card.js?v=2a0a4e3abb7b';
import {state} from '../../core/state.js?v=2a0a4e3abb7b';
import {api,projectQuery} from '../../core/api.js?v=2a0a4e3abb7b';
import {refresh,repaint,navigate} from '../../core/events.js?v=2a0a4e3abb7b';
import {T,esc,icon,heading,btn,panel,badge,empty,toast,labelName,modal,closeModal,field,formEnd} from '../../core/ui.js?v=2a0a4e3abb7b';
let row=null,labels=[],preferences={},sentence,spans=[],picked=new Set(),lastPick=null,note='',history=[],lastSaved=null,goldDraft=null,openedAt=Date.now();
const rememberNote=()=>{const v=document.querySelector('#annotation-note');if(v)note=v.value;};
export async function load(){let id=sessionStorage.getItem('annotaflow.openComment');sessionStorage.removeItem('annotaflow.openComment');const draft=sessionStorage.getItem('annotaflow.goldDraft');goldDraft=draft?JSON.parse(draft):null;sessionStorage.removeItem('annotaflow.goldDraft');if(goldDraft)id=goldDraft.id;await fetchRow(id);}
async function fetchRow(id,after){const sourceId=sessionStorage.getItem('annotaflow.annotationSource.'+state.workspace.project.id);const result=await api('studio/workspace'+projectQuery()+(!id&&sourceId?'&source='+encodeURIComponent(sourceId):'')+(id?'&comment='+id:'')+(after?'&after='+after:''));openedAt=Date.now();row=result.comment;labels=result.labels||[];preferences=result.preferences||state.workspace.preferences;spans=row?.mine?.spans?structuredClone(row.mine.spans):[];sentence=row?.mine?.status==='submitted'?row.mine.label:undefined;note=row?.mine?.note||'';picked=new Set();lastPick=null;if(goldDraft){sentence=goldDraft.label;spans=goldDraft.spans||[];note='';}if(row)history.push(row.id);}
function color(key){const c=labels.find(l=>l.key===key)?.color;return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#6d85a4';}
function textTokens(){const chars=Array.from(row.text);let cursor=0;return row.tokens.map((t,i)=>{const gap=esc(chars.slice(cursor,t.start).join(''));cursor=t.end;const marked=spans.find(s=>s.start<=t.start&&s.end>=t.end);return gap+`<button type="button" class="word-token ${picked.has(i)?'picked':''} ${marked?'marked':''}" style="--span-color:${color(marked?.label)}" data-action="annotation:token" data-index="${i}" aria-pressed="${picked.has(i)}" title="${marked?esc(labelName(marked.label)):T('Chọn từ','Select word')}">${esc(t.text)}</button>`;}).join('')+esc(chars.slice(cursor).join(''));}
export function render(){const p=state.workspace.project;const locked=preferences.locked||preferences.archived;return heading(goldDraft?T('Phân xử nhãn & cụm từ','Adjudicate labels & spans'):T('Gán nhãn bình luận','Label comments'),T('Chọn một nhãn để lưu và chuyển sang bình luận tiếp theo.','Choose a label to save and move to the next comment.'),(p.can_manage&&!locked?btn(T('Tạo nhãn','Create label'),'annotation:createLabel','','plus'):'')+btn(T('Hướng dẫn','Guidelines'),'annotation:guide','','help')+(sessionStorage.getItem('annotaflow.annotationSource.'+state.workspace.project.id)?btn(T('Gán nhãn mọi nguồn','Annotate all sources'),'annotation:allSources'):'' ))+(!row?panel(T('Hàng đợi của bạn','Your queue'),empty(T('Không còn mẫu phù hợp','No eligible samples'),T('Bạn đã xử lý các mẫu còn thiếu người gán. Chọn một mẫu từ trang Dữ liệu để xem hoặc sửa nhãn của mình.','You have handled the eligible queue. Open a record from Data to revisit your annotation.'),`<a class="btn primary" href="#datasets">${T('Đến dữ liệu','Open data')}${icon('arrow',14)}</a>`)): `<div class="annotation-layout"><section class="panel annotation-panel"><div class="panel-head"><div><h2>${T('Bình luận','Comment')} #${row.id}${goldDraft?' · GOLD':''}</h2><small>${esc(row.source||T('Dữ liệu dự án','Project data'))}${row.author?' · '+esc(row.author):''}</small></div><span class="count-pill">${row.annotation_count||0} / ${preferences.redundancy} ${T('người','people')}</span></div><div class="annotation-body">${locked?`<div class="info-banner">${icon('lock',17)}${T('Dự án đã khóa. Bạn có thể xem nhãn; quản lý cần mở khóa để lưu thay đổi.','The project is locked. A manager must unlock it before annotations can be saved.')}</div>`:''}${commentCard(row)}<div class="annotation-divider"></div><label>${T('Chọn nhãn cho bình luận','Choose a label for this comment')}</label><div class="sentence-options">${labels.map((l,i)=>`<button type="button" class="schema-option ${sentence===l.key?'selected':''}" style="--label-color:${color(l.key)}" data-action="annotation:sentence" ${locked?'disabled':''} data-label="${esc(l.key)}" aria-pressed="${sentence===l.key}"><span class="schema-dot"></span><b>${esc(l.name)}</b><kbd>${i+1}</kbd></button>`).join('')}<button type="button" class="schema-option ${sentence===null?'selected':''}" data-action="annotation:sentence" ${locked?'disabled':''} data-label="__NONE__" aria-pressed="${sentence===null}">${T('Không gán nhãn câu','No sentence label')}</button></div><details class="annotation-extra" ${picked.size||spans.length?'open':''}><summary>${T('Gán nhãn từ / cụm từ (tùy chọn)','Word / phrase labels (optional)')}</summary><div class="text-editor">${textTokens()}</div><div class="span-toolbar"><span>${icon('edit',14)}${picked.size} ${T('từ đã chọn','words selected')}</span><select id="span-label" aria-label="${T('Nhãn cụm từ','Span label')}">${labels.map(l=>`<option value="${esc(l.key)}">${esc(l.name)}</option>`).join('')}</select>${btn(T('Gán cụm từ','Label span'),'annotation:addSpan','sm','',''+(!picked.size?'disabled':''))}${btn(T('Bỏ chọn','Clear selection'),'annotation:clearPick','sm')}</div><p class="annotation-hint">${T('Bấm từng từ; giữ Shift rồi bấm để chọn một dải. Nhãn câu và nhãn cụm từ được lưu riêng.','Click words; Shift-click to select a range. Sentence labels and span labels are saved separately.')}</p><div class="span-list">${spans.map((s,i)=>`<div class="span-chip" style="--span-color:${color(s.label)}"><span>“${esc(Array.from(row.text).slice(s.start,s.end).join(''))}”</span><b>${esc(labelName(s.label))}</b>${btn(icon('close',12),'annotation:removeSpan','icon-btn','',`data-index="${i}" aria-label="${T('Xóa cụm từ','Remove span')} ${i+1}"`)}</div>`).join('')||`<p class="muted">${T('Chưa đánh dấu cụm từ nào.','No spans marked.')}</p>`}</div></details><details class="annotation-extra" ${goldDraft?'open':''}><summary>${T('Thêm ghi chú','Add a note')}</summary><label for="annotation-note">${goldDraft?T('Lý do phân xử (bắt buộc)','Adjudication reason (required)'):T('Ghi chú (không bắt buộc)','Optional note')}</label><textarea id="annotation-note" class="workspace-note" placeholder="${T('Giải thích quyết định khi cần…','Explain your decision if needed…')}">${esc(note)}</textarea></details><div class="workspace-submit"><div class="flex gap8">${btn(T('Trước','Previous'),'annotation:previous','sm','',history.length<2?'disabled':'')}${!goldDraft?btn(T('Bỏ qua','Skip'),'annotation:skip','sm')+btn(T('Hoàn tác','Undo'),'annotation:undo','sm','refresh',!row.mine&&!lastSaved?'disabled':''):''}</div>${btn(goldDraft?T('Chốt gold','Save gold'):T('Lưu & tiếp tục','Save & next'),'annotation:save','primary','arrow',locked||sentence===undefined?'disabled':'')}</div></div></section><details class="annotation-extra annotation-reference"><summary>${T('Hướng dẫn, gợi ý AI và phím tắt','Guidelines, AI suggestions and shortcuts')}</summary><aside class="stack">${panel(T('Nguyên tắc dự án','Project guidelines'),`<div class="guidelines-text">${esc(preferences.guidelines||'')}</div>`,T('Thống nhất quy tắc trước khi bắt đầu.','Agree on the schema before annotating.'))}${panel(T('Gợi ý từ AI','AI suggestion'),row.ai_hidden?`<div class="info-banner">${icon('eye',17)}<span>${T('Chế độ độc lập đang ẩn gợi ý AI và nhãn cũ trước khi bạn nộp.','Independent mode hides AI and previous labels until you submit.')}</span></div>`:row.ai_label?`<div class="ai-label-block">${badge(row.ai_label)}<small>${esc(row.ai_provider||'model')}</small></div>${btn(T('Dùng gợi ý AI','Use AI suggestion'),'annotation:acceptAI','','spark')}<p class="form-hint">${T('Model gợi ý nhãn và cụm từ. Kiểm tra trước khi dùng gợi ý.','The model suggests labels and spans. Review before accepting.')}</p>`:`<p class="form-hint">${T('Bạn có thể gán nhãn trực tiếp mà chưa cần gợi ý AI.','You can annotate without an AI suggestion.')}</p>`)}${panel(T('Phím tắt','Keyboard shortcuts'),`<div class="shortcut-list"><div><kbd>1–9</kbd><span>${T('Chọn nhãn câu','Choose sentence label')}</span></div><div><kbd>Enter</kbd><span>${T('Lưu nhãn','Save annotation')}</span></div><div><kbd>N</kbd><span>${T('Bỏ qua mẫu','Skip record')}</span></div><div><kbd>Shift</kbd><span>${T('Chọn dải từ','Select a word range')}</span></div></div>`)}</aside></details></div>`);}
export async function action(name,el,event){if(name==='createLabel'){if(!state.workspace.project.can_manage||preferences.locked||preferences.archived)return;rememberNote();modal(T('Tạo nhãn mới','Create a label'),`<form data-submit="annotation:createLabel">${field('name',T('Tên nhãn','Label name'),'','text','required maxlength="120" placeholder="Ví dụ: Tích cực"')}${field('color',T('Màu nhãn','Label color'),'#2867a6','color')}<p class="form-hint">${T('Nhãn mới sẽ xuất hiện dưới bình luận để bạn chọn gán.','The new label will appear below the comment for you to select.')}</p>${formEnd(T('Tạo nhãn','Create label'))}</form>`);return;}if(name==='allSources'){sessionStorage.removeItem('annotaflow.annotationSource.'+state.workspace.project.id);history=[];await fetchRow();await repaint();return;}if(name==='guide'){toast(preferences.guidelines||T('Xem hướng dẫn của dự án.','Read the project guidelines.'));return;}if(!row)return;rememberNote();if(name==='token'){const index=Number(el.dataset.index);if(event?.shiftKey&&lastPick!==null){const lo=Math.min(index,lastPick),hi=Math.max(index,lastPick);for(let i=lo;i<=hi;i++)picked.add(i);}else if(picked.has(index))picked.delete(index);else picked.add(index);lastPick=index;await repaint();return;}if(name==='sentence'){if(preferences.locked||preferences.archived)return;sentence=el.dataset.label==='__NONE__'?null:el.dataset.label;if(goldDraft){await repaint();return;}await action('save',el,event);return;}if(name==='clearPick'){picked.clear();await repaint();return;}if(name==='addSpan'){const key=document.querySelector('#span-label').value;const indices=[...picked].sort((a,b)=>a-b);const groups=[];for(const i of indices){if(!groups.length||groups.at(-1).at(-1)!==i-1)groups.push([i]);else groups.at(-1).push(i);}for(const g of groups){const start=row.tokens[g[0]].start,end=row.tokens[g.at(-1)].end;spans=spans.filter(s=>s.end<=start||s.start>=end);spans.push({start,end,label:key});}spans.sort((a,b)=>a.start-b.start);picked.clear();await repaint();return;}if(name==='removeSpan'){spans.splice(Number(el.dataset.index),1);await repaint();return;}if(name==='acceptAI'){sentence=row.ai_label;spans=row.ai_spans?structuredClone(row.ai_spans):[];await repaint();return;}if(name==='previous'){history.pop();const id=history.pop();if(id)await fetchRow(id);await repaint();return;}if(name==='undo'){const id=row.mine?row.id:lastSaved;if(!id)return;await api(`studio/comments/${id}/undo`,{project:state.workspace.project.id});await fetchRow(id);await repaint();toast(T('Đã hoàn tác thay đổi gần nhất.','Latest change undone.'));return;}if(name==='save'||name==='skip'){if(name==='save'&&sentence===undefined)return;if(goldDraft){if(!note.trim())throw new Error(T('Cần lý do phân xử.','An adjudication reason is required.'));await api(`studio/comments/${row.id}/gold`,{project:state.workspace.project.id,label:sentence,spans,note});goldDraft=null;toast(T('Đã lưu nhãn gold.','Gold annotation saved.'));navigate('quality');return;}const id=row.id;await api(`studio/comments/${id}/annotation`,{project:state.workspace.project.id,label:sentence,spans,note,status:name==='skip'?'skipped':'submitted',seconds:Math.min(3600,(Date.now()-openedAt)/1000),revision:row.mine?.revision||0});lastSaved=id;await fetchRow();await repaint();toast(name==='skip'?T('Đã bỏ qua mẫu.','Record skipped.'):T('Đã lưu nhãn và lịch sử thay đổi.','Annotation and revision history saved.'));}}
export function keyboard(e){if(!row)return;if(/^[1-9]$/.test(e.key)){const l=labels[Number(e.key)-1];if(l)document.querySelector(`[data-action="annotation:sentence"][data-label="${l.key}"]`)?.click();}if(e.key==='Enter'){e.preventDefault();document.querySelector('[data-action="annotation:save"]:not(:disabled)')?.click();}if(e.key.toLowerCase()==='n'&&!goldDraft)document.querySelector('[data-action="annotation:skip"]')?.click();}

export async function submit(name,form){
 if(name!=='createLabel')return;
 if(!state.workspace.project.can_manage||preferences.locked||preferences.archived)throw new Error(T('Bạn không thể tạo nhãn trong dự án này.','You cannot create labels in this project.'));
 const values=Object.fromEntries(new FormData(form));
 const labelName=String(values.name||'').trim();
 if(!labelName)throw new Error(T('Nhập tên nhãn.','Enter a label name.'));
 if(state.workspace.labels.some(l=>l.name.trim().toLocaleLowerCase()===labelName.toLocaleLowerCase()))throw new Error(T('Tên nhãn đã tồn tại.','A label with this name already exists.'));
 const result=await api('studio/labels',{project:state.workspace.project.id,key:'LABEL_'+crypto.randomUUID().replaceAll('-','').toUpperCase(),name:labelName,color:values.color,enabled:true,order:Math.min(99,Math.max(-1,...state.workspace.labels.map(l=>Number(l.order)||0))+1)});
 state.workspace.labels=result.labels;
 labels=result.labels.filter(l=>l.enabled);
 closeModal();await repaint();toast(T('Đã tạo nhãn. Chọn nhãn bên dưới bình luận để gán.','Label created. Select it below the comment to annotate.'));
}
